<!-- components/asset/AssetStatsCard.vue -->
<template>
  <view class="stats-card">
    <!-- 顶部：标题 + 筛选 -->
    <view class="header">
      <text class="title">{{ title }} {{ countText }}</text>
      <view class="filters">
        <!-- <view
          v-for="(filter, index) in filters"
          :key="index"
          class="filter-btn"
          @click="showFilterMenu(filter)"
        >
          <text class="selected-text">{{ filter }}</text>
        </view> -->
        <view class="filter-btn">
          <Dropdown
            v-model="statusValue"
            :options="statusOptions"
            :support-submenu=false
            title="状态"
            width="130rpx"
            :hide-arrow="true" 
            @change="handleFilterChange('状态', statusValue)"
          />
        </view>
        <view class="filter-btn">
          <Dropdown
            v-model="sortValue"
            :options="sortOptions"
            :support-submenu=false
            title="排序"
            width="116rpx"
            :hide-arrow="true" 
            @change="handleFilterChange('排序', sortValue)"
          />
        </view>
      </view>
    </view>

    <!-- 底部：双列统计 -->
    <view class="stats-row">
      <view class="col">
        <text class="label">{{ leftLabel }}</text>
        <text class="value">{{ formatAmount(props.leftValue) }}</text>
      </view>
      <view class="divider"></view>
      <view class="col">
        <text class="label">{{ rightLabel }}</text>
        <text class="value">{{ formatAmount(props.rightValue) }}</text>
      </view>
    </view>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { formatAmount } from '@/utils/currency'
import Dropdown from '../common/Dropdown.vue'

const props = defineProps({
  title: {
    type: String,
    default: '我的资产'
  },
  count: {
    type: Number,
    default: 0
  },
  totalCount: {
    type: Number,
    default: 0
  },
  leftLabel: {
    type: String,
    default: '总资产'
  },
  leftValue: {
    type: [String, Number],
    default: 0
  },
  rightLabel: {
    type: String,
    default: '总日均'
  },
  rightValue: {
    type: [String, Number],
    default: 0
  }
})

const emit = defineEmits(['filter-change'])

// 状态选项
const statusOptions = ['在用', '退役', '预购入', '闲置'].map(label => ({
  label,
  value: label
}))
// 排序选项
const sortOptions = ['天数', '日均', '金额'].map(label => ({
  label,
  value: label
}))

// 响应式变量
const statusValue = ref('')
const sortValue = ref('')

// 格式化显示文本：如 “3/10”
const countText = computed(() => {
  return `${props.count}/${props.totalCount}`
})

// 处理筛选变化
const handleFilterChange = (type, value) => {
  emit('filter-change', {
    type,
    value
  })
}

</script>

